<?php $any = array_filter($r); ?>
<?php if ($q === ''): ?><?= a_empty('🔎', __('Cerca nel tuo negozio'), __('Scrivi un nome prodotto, uno SKU, un numero ordine o un\'email.')) ?>
<?php elseif (!$any): ?><?= a_empty('🤷', __('Nessun risultato'), __('Prova con un\'altra parola.')) ?><?php endif ?>
<?php if ($r['products']): ?><div class="card"><h2><?= e(__('Prodotti')) ?></h2><table><tbody><?php foreach ($r['products'] as $p): ?><tr><td style="width:56px"><img class="thumb" src="<?= e(upload_url($p['image'], 400)) ?>" alt="" width="42" height="42"></td><td><a href="<?= e(url('admin/products/' . $p['id'])) ?>"><strong><?= e($p['name']) ?></strong></a><div class="muted"><?= e($p['sku']) ?></div></td><td><?= a_status($p['status']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<?php if ($r['orders']): ?><div class="card"><h2><?= e(__('Ordini')) ?></h2><table><tbody><?php foreach ($r['orders'] as $o): ?><tr><td><a href="<?= e(url('admin/orders/' . $o['id'])) ?>"><strong><?= e($o['number']) ?></strong></a></td><td><?= e($o['email']) ?></td><td><?= a_status($o['status']) ?></td><td class="right"><?= e(Alien\Core\Money::format((int)$o['total'], $o['currency'])) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<?php if ($r['customers']): ?><div class="card"><h2><?= e(__('Clienti')) ?></h2><table><tbody><?php foreach ($r['customers'] as $c): ?><tr><td><?= e($c['name']) ?></td><td><a href="<?= e(url('admin/orders?q=' . urlencode($c['email']))) ?>"><?= e($c['email']) ?></a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<?php if ($r['pages']): ?><div class="card"><h2><?= e(__('Pagine e blog')) ?></h2><table><tbody><?php foreach ($r['pages'] as $p): ?><tr><td><a href="<?= e(url('admin/pages/' . $p['id'])) ?>"><?= e($p['title']) ?></a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
